{
  "cases": [
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"alpha\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":5},{\"op\":\"stock\",\"tenant\":\"beta\",\"sku\":\"widget\"}]",
      "family": "tenant_isolation",
      "name": "cross tenant stock visibility after reservation"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"atlas\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\"beacon\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"stock\",\"tenant\":\"atlas\",\"sku\":\"widget\"}]",
      "family": "tenant_isolation",
      "name": "shared key independent stock counts"
    },
    {
      "actions_json": "[{\"op\":\"release\",\"tenant\":\"alpha\",\"key\":\"ghost-key\"}]",
      "family": "idempotency",
      "name": "release unknown key returns error"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"delta\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":10},{\"op\":\"reserve\",\"tenant\":\"delta\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":10},{\"op\":\"stock\",\"tenant\":\"delta\",\"sku\":\"widget\"}]",
      "family": "idempotency",
      "name": "idempotent retry preserves inventory level"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"gamma\",\"key\":\"k1\",\"sku\":\"sensor\",\"qty\":1},{\"op\":\"reserve\",\"tenant\":\"gamma\",\"key\":\"k1\",\"sku\":\"sensor\",\"qty\":1},{\"op\":\"release\",\"tenant\":\"gamma\",\"key\":\"k1\"},{\"op\":\"release\",\"tenant\":\"gamma\",\"key\":\"k1\"},{\"op\":\"stock\",\"tenant\":\"gamma\",\"sku\":\"sensor\"}]",
      "family": "idempotency",
      "name": "double release does not double restore stock"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"epsilon\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":3},{\"op\":\"reserve\",\"tenant\":\"epsilon\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":4}]",
      "family": "payload_binding",
      "name": "conflict on different quantity for same key"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"zeta\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\"zeta\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":2,\"extra_field\":\"ignored\"}]",
      "family": "payload_binding",
      "name": "idempotency with extra fields ignored"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"theta\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":-1}]",
      "family": "validation",
      "name": "negative quantity rejected"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"iota\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":1.5}]",
      "family": "validation",
      "name": "float quantity rejected"
    },
    {
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"kappa\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":11}]",
      "family": "validation",
      "name": "quantity over max rejected"
    }
  ]
,
  "rationale": "This suite addresses the specific counterexamples observed in Round 2's rejection. The 'Rejected' decision cited 'no strict validation gain or a correctness regression', which implies the previous suite failed to detect new bugs or introduced false positives. However, the observed counterexamples clearly show critical failures in tenant isolation (stock leaking across tenants), idempotency (retry consuming stock), and payload binding (conflict not raised). The proposed cases directly target these failures: cross-tenant stock checks verify isolation boundaries; idempotent retries with stock checks verify state preservation; and explicit conflict/invalidity tests ensure input validation is robust. These are distinct from Round 1's accepted suite by focusing on the *interaction* between operations (e.g., reserve then check other tenant) rather than just sequential operations within one tenant."
}
